{
  const rows = await FileAttachment("sales.csv").csv({typed: true});
  const year = new Date().getFullYear() - 1;
  const months = d3.range(12).map(i => new Date(Date.UTC(year, i, 1)));
  const sums = d3.rollup(rows.filter(r => new Date(r.date).getUTCFullYear() === year), v => d3.sum(v, d => d.revenue), r => new Date(r.date).getUTCMonth());
  const data = months.map((m, i) => ({month: m, revenue: sums.get(i) ?? 0}));
  return Plot.plot({
    width: 960, height: 480, marginLeft: 70, style: {fontSize: "14px"},
    title: `Monthly revenue, ${year}`,
    x: {type: "band", tickFormat: d => d3.utcFormat("%b")(d), label: null},
    y: {grid: true, label: "Revenue ($)", tickFormat: "s"},
    marks: [
      Plot.lineY(data, {x: "month", y: "revenue", stroke: "steelblue", strokeWidth: 2.5}),
      Plot.dot(data, {x: "month", y: "revenue", fill: "steelblue", r: 5}),
      Plot.text(data, {x: "month", y: "revenue", text: d => d3.format(",")(d.revenue), dy: -12, fontSize: 11}),
      Plot.ruleY([0])
    ]
  });
}

